<?php
declare(strict_types=1);namespace App\Controllers\Api;use App\Core\{Request,Response};use App\Services\NodeRtmpService;use Throwable;
final class NodeRtmpController extends ApiController{public function __construct(private readonly NodeRtmpService $rtmp){}public function pending(Request $r):void{try{$this->ok($this->rtmp->pending((int)$r->attribute('node_id'))??['pending'=>false]);}catch(Throwable $e){Response::json(['ok'=>false,'error'=>['code'=>'rtmp_task_error','message'=>$e->getMessage()]],422);}}public function result(Request $r):void{try{$this->rtmp->result((int)$r->attribute('node_id'),$r->int('config_id'),$r->int('version'),filter_var($r->input['success']??false,FILTER_VALIDATE_BOOL),$r->string('error')?:null);$this->ok(['accepted'=>true]);}catch(Throwable $e){Response::json(['ok'=>false,'error'=>['code'=>'rtmp_result_error','message'=>$e->getMessage()]],422);}}}
